    const minutes = [10, 15, 20, 30].map(function (value) { return "<button type=\"button\" class=\"" + (state.dailyMinutes === value ? "is-active" : "") + "\" data-hhc-minutes=\"" + value + "\">" + value + " phút</button>"; }).join("");
    return "<main class=\"hhc-main hhc-onboarding\"><section class=\"hhc-onboarding-hero\"><div><span class=\"hhc-kicker\">LỘ TRÌNH TIẾNG TRUNG CHO NGƯỜI VIỆT</span><h1>Từ số 0 đến đích cao nhất HSK 9, từng bước một.</h1><p>Bạn không cần biết Pinyin hay chữ Hán. HH Chinese sẽ giải thích bằng tiếng Việt, chọn đúng bài tiếp theo và chỉ mở đáp án sau khi bạn tự làm.</p><div class=\"hhc-onboarding-promise\"><span>① Nghe âm</span><span>② Nói lại</span><span>③ Học câu</span><span>④ Nhận mặt chữ</span><span>⑤ Ôn đúng lúc</span></div></div><div class=\"hhc-zero-orb\" aria-hidden=\"true\"><i></i><strong>零</strong><span>→ HSK 9</span></div></section><section class=\"hhc-card hhc-onboarding-card\"><header><div><small>BƯỚC 1</small><h2>Bạn đang ở đâu?</h2></div><span>Không có câu trả lời sai</span></header><div class=\"hhc-entry-grid\">" + entries + "</div></section><section class=\"hhc-card hhc-onboarding-card\"><header><div><small>BƯỚC 2</small><h2>Bạn muốn học bao lâu mỗi ngày?</h2></div><span>Có thể đổi sau</span></header><div class=\"hhc-minute-grid\">" + minutes + "</div><p class=\"hhc-muted\">Ưu tiên duy trì đều đặn. Hệ thống dùng thời lượng này để điều chỉnh mục tiêu ngày, không hứa hẹn thời gian đỗ HSK.</p></section><section class=\"hhc-onboarding-footer\"><div><strong>Mục tiêu mặc định: HSK 9</strong><span>HSK 7–9 là nhóm nâng cao chung. Lộ trình gồm nghe, nói, đọc, viết và dịch; mô phỏng không thay thế chứng chỉ chính thức.</span></div><button class=\"is-primary\" type=\"button\" data-hhc-start-course>Bắt đầu bài đầu tiên →</button></section></main>";
